<?php
require_once __DIR__ . '/../includes/config.php';
require_role('admin');db_required();if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['type'];$id=(int)$_POST['id'];$action=$_POST['action'];$table=$type==='volunteer'?'volunteer_applications':'coordinator_applications';$status=$action==='approve'?'approved':'rejected';$pdo->prepare("UPDATE {$table} SET status=?,reviewed_at=NOW() WHERE id=?")->execute([$status,$id]);flash('success',ucfirst($type).' application '.$status.'.');redirect('/admin/applications.php');}$vol=$pdo->query("SELECT va.*,u.name,u.email,e.title FROM volunteer_applications va JOIN users u ON u.id=va.user_id JOIN events e ON e.id=va.event_id ORDER BY FIELD(va.status,'pending','approved','rejected'),va.created_at DESC")->fetchAll();$coord=$pdo->query("SELECT ca.*,u.name,u.email,e.title FROM coordinator_applications ca JOIN users u ON u.id=ca.user_id JOIN events e ON e.id=ca.event_id ORDER BY FIELD(ca.status,'pending','approved','rejected'),ca.created_at DESC")->fetchAll();$page_title='Team Applications';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="section-kicker">People management</div><h2 class="fw-bold mb-4">Volunteer & coordinator applications</h2><div class="row g-4"><div class="col-xl-7"><div class="dash-card overflow-hidden"><div class="p-4 border-bottom"><h5 class="mb-0">Volunteers</h5></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Event</th><th>Position</th><th>Action</th></tr></thead><tbody><?php foreach($vol as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['position'])?></td><td><?php if($r['status']==='pending'):?><form method="post" class="d-flex gap-1"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="type" value="volunteer"><button name="action" value="approve" class="btn btn-sm btn-success rounded-pill">✓</button><button name="action" value="reject" class="btn btn-sm btn-outline-danger rounded-pill">×</button></form><?php else:?><?=status_badge($r['status'])?><?php endif;?></td></tr><?php endforeach;if(!$vol):?><tr><td colspan="4" class="empty">No volunteer applications.</td></tr><?php endif;?></tbody></table></div></div></div><div class="col-xl-5"><div class="dash-card overflow-hidden"><div class="p-4 border-bottom"><h5 class="mb-0">Coordinators</h5></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Event</th><th>Action</th></tr></thead><tbody><?php foreach($coord as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['title'])?></td><td><?php if($r['status']==='pending'):?><form method="post" class="d-flex gap-1"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="type" value="coordinator"><button name="action" value="approve" class="btn btn-sm btn-success rounded-pill">✓</button><button name="action" value="reject" class="btn btn-sm btn-outline-danger rounded-pill">×</button></form><?php else:?><?=status_badge($r['status'])?><?php endif;?></td></tr><?php endforeach;if(!$coord):?><tr><td colspan="3" class="empty">No coordinator applications.</td></tr><?php endif;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
